local function b64d(d)
  local r
  pcall(function()
    if syn and syn.crypt and syn.crypt.base64 then r=syn.crypt.base64.decode(d);return end
    if crypt and crypt.base64 then r=crypt.base64.decode(d);return end
    if base64_decode then r=base64_decode(d);return end
    if http and http.base64decode then r=http.base64decode(d);return end
    error("x")
  end)
  if type(r)=="string" and #r>0 then return r end
  local B="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  d=string.gsub(d,"[^"..B.."=]","")
  return (d:gsub(".",function(x)
    if x=="=" then return "" end
    local r,f="",(B:find(x)-1)
    for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and "1" or "0") end
    return r
  end):gsub("%d%d%d?%d?%d?%d?%d?%d?",function(x)
    if #x~=8 then return "" end
    local c=0
    for i=1,8 do c=c+(x:sub(i,i)=="1" and 2^(8-i) or 0) end
    return string.char(c)
  end))
end

if type(writefile)~="function" or type(getcustomasset)~="function" then
  error("[Bindz] Can writefile/getcustomasset")
end
writefile("bindz_bg.png", b64d(IMG))
