-- Traffic lights
local function mkLight(x,col,hcol,cb)
  local d=Instance.new("TextButton")
  d.Size=UDim2.fromOffset(12,12)
  d.Position=UDim2.fromOffset(x,TB/2-6)
  d.BackgroundColor3=col
  d.BorderSizePixel=0
  d.Text=""
  d.AutoButtonColor=false
  d.ZIndex=7
  d.Parent=tbar
  Instance.new("UICorner",d).CornerRadius=UDim.new(1,0)
  local s=Instance.new("UIStroke",d)
  s.Color=Color3.fromRGB(0,0,0)
  s.Transparency=0.7
  s.Thickness=0.5
  d.MouseEnter:Connect(function() TS:Create(d,TweenInfo.new(0.15),{BackgroundColor3=hcol}):Play() end)
  d.MouseLeave:Connect(function() TS:Create(d,TweenInfo.new(0.15),{BackgroundColor3=col}):Play() end)
  d.MouseButton1Down:Connect(function() TS:Create(d,TweenInfo.new(0.08),{Size=UDim2.fromOffset(10,10),Position=UDim2.fromOffset(x+1,TB/2-5)}):Play() end)
  d.MouseButton1Up:Connect(function() TS:Create(d,TweenInfo.new(0.15),{Size=UDim2.fromOffset(12,12),Position=UDim2.fromOffset(x,TB/2-6)}):Play() end)
  if cb then d.MouseButton1Click:Connect(cb) end
  return d
end

local isMin=false
local isMax=false
local function calcCenterPos(sz)
  local cam=workspace.CurrentCamera
  local vp=cam and cam.ViewportSize or Vector2.new(1920,1080)
  return UDim2.fromOffset(math.floor((vp.X-sz.X)/2),math.floor((vp.Y-sz.Y)/2))
end

local function setSizeAnimated(sz,keepPos)
  local cur=menu.AbsoluteSize
  local curPos=menu.AbsolutePosition
  local cx,cy=curPos.X+cur.X/2,curPos.Y+cur.Y/2
  local nx,ny=cx-sz.X/2,cy-sz.Y/2
  if not keepPos then
    local cp=calcCenterPos(sz)
    nx,ny=cp.X.Offset,cp.Y.Offset
  end
  TS:Create(menu,TweenInfo.new(0.45,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{
    Size=sz,
    Position=UDim2.fromOffset(math.floor(nx),math.floor(ny))
  }):Play()
end

