-- ░ SHOW PAGE ░
local function showPage(idx,from)
  if current==idx then return end
  local prev=current
  current=idx
  local p=pages[idx]
  if not p then return end
  local dir=(from and from>idx) and -1 or 1
  p.Visible=true
  p.Position=UDim2.fromOffset(dir*60,0)
  if prev and pages[prev] then
    local pp=pages[prev]
    TS:Create(pp,TweenInfo.new(0.24,Enum.EasingStyle.Quart,Enum.EasingDirection.In),{Position=UDim2.fromOffset(-dir*50,0)}):Play()
    task.delay(0.22,function() pp.Visible=false end)
  end
  TS:Create(p,TweenInfo.new(0.42,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{Position=UDim2.fromOffset(0,0)}):Play()
  -- Stagger cards
  task.delay(0.05,function()
    local delay=0
    for _,ch in ipairs(p:GetChildren()) do
      if ch:IsA("TextButton") then
        local orig=ch.Position
        ch.Position=UDim2.fromOffset(orig.X.Offset+30,orig.Y.Offset)
        ch.BackgroundTransparency=1
        task.delay(delay,function()
          TS:Create(ch,TweenInfo.new(0.5,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{Position=orig,BackgroundTransparency=0.42}):Play()
        end)
        delay=delay+0.06
      end
    end
  end)
end

