local function selectNav(i)
  for j,nb in ipairs(navBtns) do
    local nl=nb:FindFirstChild("Lbl")
    local ni=nb:FindFirstChild("Ico")
    local nind=nb:FindFirstChild("Ind")
    if j==i then
      TS:Create(nb,TweenInfo.new(0.25),{BackgroundColor3=BG2,BackgroundTransparency=0.15}):Play()
      if nl then TS:Create(nl,TweenInfo.new(0.25),{TextColor3=GOLD_LT,Position=UDim2.fromOffset(44,0)}):Play() end
      if ni then TS:Create(ni,TweenInfo.new(0.25),{TextColor3=GOLD_LT}):Play() end
      if nind then TS:Create(nind,TweenInfo.new(0.32,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{Size=UDim2.new(0,3,0,28)}):Play() end
    else
      TS:Create(nb,TweenInfo.new(0.25),{BackgroundTransparency=1}):Play()
      if nl then TS:Create(nl,TweenInfo.new(0.25),{TextColor3=MUTED,Position=UDim2.fromOffset(40,0)}):Play() end
      if ni then TS:Create(ni,TweenInfo.new(0.25),{TextColor3=MUTED}):Play() end
      if nind then TS:Create(nind,TweenInfo.new(0.25),{Size=UDim2.new(0,3,0,0)}):Play() end
    end
  end
end

