-- ░ DRAGGING (đã fix) ░
local dragging=false
local dragStart,dragOrigin
local dragInput

local function clampPos(x,y)
  local cam=workspace.CurrentCamera
  local vp=cam and cam.ViewportSize or Vector2.new(1920,1080)
  local sz=menu.AbsoluteSize
  local maxX=math.max(0,vp.X-sz.X)
  local maxY=math.max(0,vp.Y-sz.Y)
  return math.clamp(x,0,maxX),math.clamp(y,0,maxY)
end

local function stopDrag()
  dragging=false
  dragInput=nil
end

dragZone.InputBegan:Connect(function(i)
  if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then
    dragging=true
    dragInput=i
    dragStart=Vector2.new(i.Position.X,i.Position.Y)
    dragOrigin=menu.AbsolutePosition
    i.Changed:Connect(function()
      if i.UserInputState==Enum.UserInputState.End then stopDrag() end
    end)
  end
end)

UIS.InputChanged:Connect(function(i)
  if not dragging then return end
  if i==dragInput or i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch then
    local d=Vector2.new(i.Position.X,i.Position.Y)-dragStart
    local nx,ny=clampPos(dragOrigin.X+d.X,dragOrigin.Y+d.Y)
    menu.Position=UDim2.fromOffset(math.floor(nx),math.floor(ny))
  end
end)

-- ░ VIEWPORT RESIZE re-center nếu chưa drag ░
local everDragged=false
dragZone.InputBegan:Connect(function() everDragged=true end)

local function reClamp()
  local p=menu.AbsolutePosition
  local s=menu.AbsoluteSize
  local nx,ny=clampPos(p.X,p.Y)
  if nx~=p.X or ny~=p.Y then
    menu.Position=UDim2.fromOffset(math.floor(nx),math.floor(ny))
  end
end

if workspace.CurrentCamera then
  workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
    task.wait()
    if everDragged then reClamp() else menu.Position=calcCenterPos(menu.AbsoluteSize) end
  end)
end

-- ░ ENTRANCE ░
local function entrance()
  local cam=workspace.CurrentCamera
  local vp=cam and cam.ViewportSize or Vector2.new(1920,1080)
  local iW,iH=W*0.78,H*0.78
  menu.Size=UDim2.fromOffset(iW,iH)
  menu.Position=UDim2.fromOffset(math.floor((vp.X-iW)/2),math.floor((vp.Y-iH)/2))
  menu.BackgroundTransparency=1
  bg.ImageTransparency=1
  ov.BackgroundTransparency=1
  ms.Transparency=1
  tbar.BackgroundTransparency=1
  sidebar.BackgroundTransparency=1
  sbar.BackgroundTransparency=1
  ti.TextTransparency=1
  vb.TextTransparency=1
  sLeft.TextTransparency=1
  sRight.TextTransparency=1
  sep.BackgroundTransparency=1
  sbSep.BackgroundTransparency=1

  local fw,fh=math.max(0,vp.X/2-W/2),math.max(0,vp.Y/2-H/2)
  TS:Create(menu,TweenInfo.new(0.75,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{
    Size=UDim2.fromOffset(W,H),
    Position=UDim2.fromOffset(math.floor(fw),math.floor(fh)),
    BackgroundTransparency=1
  }):Play()
  TS:Create(bg,TweenInfo.new(1,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{ImageTransparency=0.15}):Play()
  TS:Create(ov,TweenInfo.new(1,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{BackgroundTransparency=1}):Play()
  TS:Create(ms,TweenInfo.new(1.2,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{Transparency=0.25}):Play()
  TS:Create(tbar,TweenInfo.new(0.8,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{BackgroundTransparency=0.15}):Play()
  TS:Create(sidebar,TweenInfo.new(0.9,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{BackgroundTransparency=0.35}):Play()
  TS:Create(sbar,TweenInfo.new(0.9,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{BackgroundTransparency=0.15}):Play()
  TS:Create(ti,TweenInfo.new(0.9,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{TextTransparency=0}):Play()
  TS:Create(vb,TweenInfo.new(1),{TextTransparency=0}):Play()
  TS:Create(sLeft,TweenInfo.new(1),{TextTransparency=0}):Play()
  TS:Create(sRight,TweenInfo.new(1),{TextTransparency=0}):Play()
  TS:Create(sep,TweenInfo.new(1),{BackgroundTransparency=0.55}):Play()
  TS:Create(sbSep,TweenInfo.new(1),{BackgroundTransparency=0.75}):Play()

  -- Nav stagger
  for i,b in ipairs(navBtns) do
    local l=b:FindFirstChild("Lbl")
    local ic=b:FindFirstChild("Ico")
    if l then
      l.TextTransparency=1
      l.Position=UDim2.fromOffset(30,0)
    end
    if ic then ic.TextTransparency=1 end
    task.delay(0.35+i*0.08,function()
      if l then
        TS:Create(l,TweenInfo.new(0.42,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{TextTransparency=0,Position=UDim2.fromOffset(40,0)}):Play()
      end
      if ic then
        TS:Create(ic,TweenInfo.new(0.42),{TextTransparency=0}):Play()
      end
    end)
  end

  -- Show first page after 0.5s
  task.delay(0.6,function()
    showPage(1)
    selectNav(1)
  end)
end
entrance()

